const sfStandaloneMode=(typeof navigator!=='undefined'&&navigator.standalone===true)||(typeof window!=='undefined'&&window.matchMedia?.('(display-mode: standalone)')?.matches===true);
document.documentElement.classList.toggle('sf-standalone',sfStandaloneMode);
/* Graphite & Crimson application. Existing server RPCs remain the authority for writes. */
const SITE_VERSION='__SF_VERSION__',SITE_BADGE='__SF_BADGE__';
const BRAND_ASSET='assets/graphite/brand/';
const WRITE_RPC=new Set(['claim_team','submit_game_result','claim_dynasty_invite','create_dynasty','create_my_schedule_game','create_my_schedule_bye','validate_h2h_result','set_dynasty_active_week','create_dynasty_invite','revoke_dynasty_invite','set_coach_stream','commissioner_change_coach_program','create_next_season_with_programs','release_team','create_heisman_award','delete_heisman_award','generate_dynasty_vegas_week','generate_dynasty_vegas_line']);
const ALLOWED_RPC=new Set([...WRITE_RPC,'get_dynasty_coaches','get_dynasty_active_week','get_coach_career_stops','get_team_selection','get_schedule_team_options','get_h2h_results','get_dynasty_vegas','list_dynasty_invites','list_heisman_awards','get_coach_program_moves']);
let mutationPending=false,authMode='login',notice='',teamChoices=[],teamChoice=null,choiceQuery='',choiceConference='',choiceAvailable=true,resultDraft=null,gameOptions=[],h2hMeta={ready:false,results:[]},marketRows=[],marketStatus='idle',marketContext='',marketRequest=null,entryError='',marketAutoGenFor='',autoAdvanceFor='';
for(const r of ['joinleague','createleague','selectteam','claimreview','result','resultreview','addgame','office','market','explore'])routes.add(r);
const nativeReadingContent=content;
const nativeTeam=team;
const nativeCoach=coach;
const nativeScores=scores;
const nativeGame=gamePage;
const nativeLoadSeason=loadSeason;
const field=(id,label,type='text',extra='')=>`<label for="${id}">${esc(label)}</label><input id="${id}" name="${id}" type="${type}" ${extra}>`;
const formStatus=()=>'<p id="formMessage" class="error-message" role="alert"></p>';
const context=()=>`${dynasty?.dynasty_id||''}:${season?.season_id||''}`;
const canManage=()=>['commissioner','co_commissioner'].includes(dynasty?.role);
const activeSeason=()=>['active','setup'].includes(season?.status);
const ownProgram=()=>model.myPrograms.find(p=>p.season_id===season?.season_id);
function actionsEnabled(){return !!session()?.access_token&&activeSeason()&&!mutationPending}
function myGame(g){const p=ownProgram();return !!p&&[g?.team_id,g?.opponent_team_id].includes(p.team_id)}
function isH2H(g){const a=model.programs.find(p=>p.team_id===g?.team_id),b=model.programs.find(p=>p.team_id===g?.opponent_team_id);return !!(a?.person_id&&b?.person_id&&a.person_id!==b.person_id)}
function scoreEntryAllowed(g){return actionsEnabled()&&myGame(g)&&g?.status==='scheduled'&&!g.is_bye&&(!isH2H(g)||h2hMeta.ready)}
function setFormMessage(t){if($('formMessage'))$('formMessage').textContent=t}
async function writeAction(name,body,form,after){
 if(mutationPending||form.dataset.saved==='true')return;
 mutationPending=true;
 const controls=[...form.querySelectorAll('input,select,textarea,button')],disabled=controls.map(x=>x.disabled);
 const message=form.querySelector('[role="alert"],[role="status"]');
 const status=text=>{if(message)message.textContent=text};
 let committed=false;
 controls.forEach(x=>x.disabled=true);status('Saving…');document.body.classList.add('saving');
 try{
  if(!WRITE_RPC.has(name))throw Error('Unsupported action.');
  const result=await req('/rest/v1/rpc/'+name,{method:'POST',token:session()?.access_token,body,retry:0});
  committed=true;form.dataset.saved='true';mutationPending=false;document.body.classList.remove('saving');
  await after(result);
 }catch(e){
  if(committed){notice='Saved successfully. Refresh the league to see the updated data.';status(notice);if(!form.isConnected)render()}
  else status(e.message||'Could not save. Please try again.');
 }finally{
  mutationPending=false;document.body.classList.remove('saving');
  if(!committed)controls.forEach((x,i)=>x.disabled=disabled[i]);
 }
}
function clearNotice(){notice='';const n=$('globalNotice');if(n)n.remove()}
async function afterSeasonLoaded(){
 const key=context(),serial=loadSerial;h2hMeta={ready:false,results:[]};marketRows=[];marketStatus='idle';marketContext='';teamChoice=null;resultDraft=null;officeData=null;officeLoadedFor='';bracketRound=null;
 loadMarketLines().then(async()=>{await maybeAutoAdvanceWeek();maybeAutoGenerateLines()});
 try{const meta=await readRpc('get_h2h_results',{p_dynasty_id:dynasty.dynasty_id,p_season_id:season.season_id});if(serial!==loadSerial||key!==context())return;h2hMeta=meta?.ready?meta:{ready:false,results:[]};if(route==='advanced'||mutationPending||document.querySelector('#mainContent form')||$('detailSheet')?.open)return;const top=$('screenViewport')?.scrollTop;render();if($('screenViewport'))$('screenViewport').scrollTop=top||0}catch{}
}
async function refreshCurrent(target='home',gameId=null){const d=dynasty?.dynasty_id;if(!d)return;await loadDynasty(d);if(loadError){notice='Saved successfully. Reload the league to see the updated data.';render();return}if(gameId)selectedGame=gameId;route=target;historyReplace();render()}

function toggleAuth(mode){if(mutationPending)return;authMode=mode;render()}
loginPage=function(){return `<div class="login-hero"><img src="${ASSET}experience/tunnel.webp" alt="A football stadium seen from the tunnel"><img class="login-brand-lockup" src="${BRAND_ASSET}foundry-lockup.webp" alt="Saturday Foundry · College Dynasty Manager" width="1983" height="793"><div>${title('Welcome to Saturday Foundry','Your next chapter.','The league. The rivalries. Your legacy.')}</div></div><div class="login-body"><div class="filterbar auth-tabs"><button class="${authMode==='login'?'sel':''}" aria-pressed="${authMode==='login'}" onclick="toggleAuth('login')">Sign in</button><button class="${authMode==='signup'?'sel':''}" aria-pressed="${authMode==='signup'}" onclick="toggleAuth('signup')">Create account</button></div>${title('Saturday starts here',authMode==='login'?'Welcome back.':'Build your legacy.',authMode==='login'?'Your teams, your people, your next Saturday.':'One account for every chapter of your coaching career.')}<form onsubmit="event.preventDefault();${authMode==='login'?'login':'signup'}(this)">${authMode==='signup'?field('displayName','Coach name','text','autocomplete="nickname" maxlength="70" required'):''}${field('email','Email','email','autocomplete="username" required')}${field('password','Password','password',`autocomplete="${authMode==='login'?'current-password':'new-password'}" ${authMode==='signup'?'minlength="6"':''} required`)}<p id="loginMessage" role="alert" class="error-message">${esc(entryError)}</p><button class="primary" type="submit">${authMode==='login'?'Sign in':'Create account'}</button></form><p class="sport-note">${authMode==='login'?'Use your existing Saturday Foundry account.':'After confirming your email, sign in to join or create a league.'}</p></div>`};
async function signup(form){if(mutationPending)return;mutationPending=true;const b=form.querySelector('button[type=submit]');b.disabled=true;$('loginMessage').textContent='Creating your account…';try{const data=await req('/auth/v1/signup',{method:'POST',body:{email:form.elements.email.value.trim(),password:form.elements.password.value,data:{display_name:form.elements.displayName.value.trim()}},retry:0});form.elements.password.value='';if(data?.access_token){save(data);mutationPending=false;await start()}else{$('loginMessage').textContent='Check your email to confirm your account, then sign in.'}}catch(e){$('loginMessage').textContent=e.message}finally{mutationPending=false;b.disabled=false}}
function leagueTeam(d){return d.active_season_id?model.leaguePrograms.find(p=>p.dynasty_id===d.dynasty_id&&p.season_id===d.active_season_id)||null:null}
function leagueBadge(p){const t=p?teamData(p.team_id):{},src=p&&(safeImage(p.logo_url)||safeImage(t.logo_url)||(t.espn_team_id?`https://a.espncdn.com/i/teamlogos/ncaa/500/${encodeURIComponent(t.espn_team_id)}.png`:''));return `<img class="league-team-badge ${src?'':'league-brand-fallback'}" src="${src||BRAND_ASSET+'foundry-shield.webp'}" alt="${src?esc(p.team_name)+' logo':'Saturday Foundry'}" loading="lazy" onerror="this.onerror=null;this.src='${BRAND_ASSET}foundry-shield.webp';this.alt='Saturday Foundry';this.classList.add('league-brand-fallback')">`}
function leagueChooser(){return title('Your coaching world','Choose your league','Every dynasty has its own story.')+`<div class="league-cards">${model.dynasties.map(d=>{const p=leagueTeam(d),label=p?p.team_name:!d.active_season_id?'No active season':model.leagueProgramsReady?'No team selected':'Team info unavailable';return `<button class="league-choice" data-league="${uid(d.dynasty_id)}" onclick="loadDynasty('${uid(d.dynasty_id)}')">${leagueBadge(p)}<span><strong>${esc(d.name)}</strong><small class="league-team-name">${esc(label)}</small><small>${d.active_season_number?'Season '+esc(d.active_season_number):esc(d.status)} · ${esc(String(d.role||'member').replace('_',' '))}</small></span>${ico('arrow')}</button>`}).join('')||empty('You haven’t joined a league yet. Use an invitation from your commissioner or start a new league.')}</div><div class="entry-actions">${button('Join a league','joinleague')}${button('Create a league','createleague','secondary')}</div>`}
let leagueCardRequest=0;
async function refreshLeagueCards(){const request=++leagueCardRequest,serial=loadSerial;try{const [dynasties,programs]=await Promise.all([read('v_my_dynasties','order=joined_at.asc'),read('v_my_programs','order=dynasty_id.asc,season_id.asc,season_program_id.asc')]);if(request!==leagueCardRequest||serial!==loadSerial||!session()?.access_token||mutationPending)return;model.dynasties=dynasties;model.leaguePrograms=programs;model.leagueProgramsReady=true;if(route==='leagues'&&!$('detailSheet')?.open)render()}catch{}}
const programAwareGo=go;
go=function(r){const result=programAwareGo(r);if(r==='leagues'&&route==='leagues'&&!mutationPending)refreshLeagueCards();return result};

function joinLeague(){return title('Find your people','Join a league','Enter the invitation code from your commissioner.')+`<form class="compact-form" onsubmit="event.preventDefault();submitInvite(this)">${field('inviteCode','Invitation code','text','autocomplete="off" autocapitalize="characters" maxlength="100" required')}${formStatus()}<button class="primary" type="submit">Join league</button></form>`}
async function submitInvite(form){const code=form.elements.inviteCode.value.trim();if(!code)return;await writeAction('claim_dynasty_invite',{invite_code:code},form,async result=>{const id=Array.isArray(result)?result[0]?.dynasty_id:result?.dynasty_id;model.dynasties=await read('v_my_dynasties','order=joined_at.asc');notice='You’re in. Welcome to the league.';if(id)await loadDynasty(id);else{route='leagues';render()}})}
function createLeague(){return title('Start something great','Create your league','Set the name. Invite your people. Build the history.')+`<form class="compact-form" onsubmit="event.preventDefault();submitLeague(this)">${field('leagueName','League name','text','maxlength="100" required')}${field('shortName','Short name','text','maxlength="12"')}<label for="edition">Game edition</label><select id="edition" name="edition"><option value="27">College Football 27</option><option value="26">College Football 26</option></select>${formStatus()}<button class="primary" type="submit">Create league</button></form>`}
async function submitLeague(form){const name=form.elements.leagueName.value.trim();if(!name)return setFormMessage('Enter a league name.');await writeAction('create_dynasty',{p_name:name,p_short_name:form.elements.shortName.value.trim()||null,p_game_edition:form.elements.edition.value,p_year:null},form,async result=>{model.dynasties=await read('v_my_dynasties','order=joined_at.asc');const id=Array.isArray(result)?result[0]?.dynasty_id:result?.dynasty_id;notice='Your league is ready. Choose a program to get started.';if(id){await loadDynasty(id);await openTeamSelection()}else{route='leagues';render()}})}
async function openTeamSelection(){if(!activeSeason()||mutationPending)return;const key=context();route='selectteam';teamChoices=[];entryError='';render();try{const choices=await readRpc('get_team_selection',{p_season_id:season.season_id});if(key!==context())return;teamChoices=Array.isArray(choices)?choices:[];render()}catch(e){if(key===context()){entryError=e.message;render()}}}
function selectionPage(){const mine=ownProgram();if(mine)return title(dynasty.name,'Your program is set.',mine.team_name)+`<button class="primary" onclick="openTeam('${uid(mine.team_id)}')">View your team</button>`;const confs=[...new Set(teamChoices.map(t=>t.conference||'Independent'))].sort();const list=teamChoices.filter(t=>(!choiceAvailable||!t.claimed)&&(!choiceConference||(t.conference||'Independent')===choiceConference)&&(!choiceQuery||(t.team_name+' '+t.conference).toLowerCase().includes(choiceQuery.toLowerCase())));return title(dynasty.name,'Choose your program.','Season '+season.season_number+' · The next chapter starts here.')+`<div class="selection-filters"><div class="searchbox">${ico('search')}<input aria-label="Search programs" placeholder="Search schools" value="${esc(choiceQuery)}" oninput="filterProgramChoices(this.value)"></div><label class="sr-only" for="choiceConference">Conference</label><select id="choiceConference" onchange="choiceConference=this.value;render()"><option value="">All conferences</option>${confs.map(c=>`<option ${choiceConference===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label class="checkline"><input type="checkbox" ${choiceAvailable?'checked':''} onchange="choiceAvailable=this.checked;render()"> Available only</label></div><p class="sport-note">${teamChoices.filter(t=>!t.claimed).length} available · ${teamChoices.filter(t=>t.claimed).length} claimed</p>${entryError?`<p class="error-message">${esc(entryError)}</p><button class="secondary" onclick="openTeamSelection()">Retry</button>`:''}<div id="programChoices" class="program-grid">${choiceCards(list)}</div>${!teamChoices.length&&!entryError?empty('Loading available programs…'):''}<button class="link" onclick="go('home')">Explore the league first →</button>`}
function choiceCards(list){return list.map(t=>`<button class="program-choice" ${t.claimed?'disabled':''} onclick="chooseProgram('${uid(t.team_id)}')"><span class="choice-status">${t.claimed?'CLAIMED':'AVAILABLE'}</span>${logo(t.team_id,t.team_name)}<strong>${esc(t.team_name)}</strong><small>${esc(t.conference||'Independent')}</small><span class="rating-strip"><span>OVR <b>${esc(t.overall_rating??'—')}</b></span><span>OFF <b>${esc(t.offense_rating??'—')}</b></span><span>DEF <b>${esc(t.defense_rating??'—')}</b></span></span>${t.claimed?`<small>${esc(t.claimed_by||'Assigned coach')}</small>`:''}</button>`).join('')||empty('No programs match your search.')}
function filterProgramChoices(q){choiceQuery=q;const list=teamChoices.filter(t=>(!choiceAvailable||!t.claimed)&&(!choiceConference||(t.conference||'Independent')===choiceConference)&&(!q||(t.team_name+' '+t.conference).toLowerCase().includes(q.toLowerCase())));$('programChoices').innerHTML=choiceCards(list)}
function chooseProgram(id){const t=teamChoices.find(t=>t.team_id===id);if(!t||t.claimed||!actionsEnabled()||ownProgram())return;teamChoice={...t,seasonId:season.season_id,dynastyId:dynasty.dynasty_id};go('claimreview')}
function claimReview(){if(!teamChoice||teamChoice.seasonId!==season?.season_id)return empty('Choose an available program first.');const t=teamChoice;return title('Your next chapter','Make it yours.')+`<div class="claim-hero">${logo(t.team_id,t.team_name)}<h2>${esc(t.team_name)}</h2><p>${esc(t.conference)} · Season ${esc(season.season_number)}</p></div><p class="article-inline">You’ll become this program’s coach in ${esc(dynasty.name)}. Your completed seasons and career history stay with you.</p><form class="compact-form" onsubmit="event.preventDefault();claimProgram(this)">${formStatus()}<button type="submit" class="primary">Confirm ${esc(t.team_name)}</button><button type="button" class="secondary" onclick="go('selectteam')">Choose another team</button></form>`}
async function claimProgram(form){const t=teamChoice;if(!t||t.seasonId!==season?.season_id||t.dynastyId!==dynasty?.dynasty_id||!activeSeason())return setFormMessage('The season changed. Choose your team again.');await writeAction('claim_team',{p_season_id:t.seasonId,p_team_id:t.team_id},form,async()=>{notice='You’re the coach. Welcome to '+t.team_name+'.';await refreshCurrent('home')})}
function beginResult(id){const g=games().find(g=>g.id===id);if(!scoreEntryAllowed(g))return;resultDraft={gameId:id,context:context(),seasonId:season.season_id,myTeamId:ownProgram().team_id,away:'',home:'',overtime:false};selectedGame=id;go('result')}
function resultPage(){const g=games().find(g=>g.id===resultDraft?.gameId);if(!g||resultDraft.context!==context()||(!myGame(g)&&!(resultDraft.correction&&canManage())))return empty(resultDraft?.correction?'Choose a game in the League Office to correct its final.':'Choose one of your upcoming games to enter its result.');return title('Week '+g.week_number,(resultDraft.correction?'Correct final score':'Enter final score'),g.away+' at '+g.home)+`<form class="compact-form score-entry" onsubmit="event.preventDefault();reviewResult(this)"><div class="score-input-row">${logo(g.awayId,g.away)}${field('awayScore',g.away,'number',`min="0" max="250" inputmode="numeric" step="1" required value="${esc(resultDraft.away)}" oninput="resultDraft.away=this.value"`)}</div><div class="score-input-row">${logo(g.homeId,g.home)}${field('homeScore',g.home,'number',`min="0" max="250" inputmode="numeric" step="1" required value="${esc(resultDraft.home)}" oninput="resultDraft.home=this.value"`)}</div><label class="checkline"><input type="checkbox" name="overtime" ${resultDraft.overtime?'checked':''} onchange="resultDraft.overtime=this.checked"> Overtime</label>${formStatus()}<button type="submit" class="primary">Review final</button></form>`}
function reviewResult(form){const a=form.elements.awayScore.value,h=form.elements.homeScore.value;if(a===''||h===''||![a,h].every(v=>Number.isInteger(Number(v))&&Number(v)>=0&&Number(v)<=250)||Number(a)===Number(h))return setFormMessage('Enter two valid, non-tied final scores.');resultDraft={...resultDraft,away:Number(a),home:Number(h),overtime:form.elements.overtime.checked};go('resultreview')}
function resultReview(){const g=games().find(g=>g.id===resultDraft?.gameId);if(!g||resultDraft.context!==context())return empty('The game context changed. Open the game again.');const d=resultDraft;return title('Ready to record','Confirm the final.')+card({...g,a:d.away,h:d.home,final:true,overtime:d.overtime})+`<p class="article-inline">${d.correction?'Commissioner correction — this updates the official league record.':isH2H(g)?'The other coach will be able to confirm this result.':'This result will update your league records and standings.'}</p><form class="compact-form" onsubmit="event.preventDefault();saveResult(this)">${formStatus()}<button class="primary" type="submit">Save final score</button><button class="secondary" type="button" onclick="go('result')">Edit score</button></form>`}
async function saveResult(form){const d=resultDraft,g=games().find(g=>g.id===d?.gameId);if(!d||d.context!==context()||(d.correction?!(canManage()&&activeSeason()&&g):!scoreEntryAllowed(g)))return setFormMessage('This game can no longer be entered here. Refresh its status.');const mine=d.myTeamId===g.awayId,entryMine=g.team_id===d.myTeamId;const payload={p_game_id:g.id,p_my_score:mine?d.away:d.home,p_opponent_score:mine?d.home:d.away,p_my_rank:entryMine?g.team_rank:g.opponent_rank,p_opponent_rank:entryMine?g.opponent_rank:g.team_rank,p_overtime:d.overtime,p_network:g.network||null,p_event_name:g.event_name||null};await writeAction('submit_game_result',payload,form,async()=>{notice=d.correction?'Final score corrected.':'Final score saved.';resultDraft=null;await refreshCurrent('game',g.id)})}
function h2hStatus(g){if(!isH2H(g)||!g.final)return '';const v=h2hMeta.results?.find(v=>v.game_id===g.id);let label=!h2hMeta.ready?'Validation status is unavailable.':!v?'Historical final · No validation record.':v.status==='confirmed'?'Confirmed by both coaches':v.status==='resolved'?'Resolved by commissioner':v.status==='disputed'?'Flagged for commissioner review':'Awaiting '+(v.opponent_name||'the other coach')+'’s confirmation';const can=v?.status==='pending'&&v.opponent_person===myCoach()&&v.submitted_by!==myCoach();return `<div class="notice"><strong>Coach vs coach</strong><p>${esc(label)}</p>${can?`<button class="secondary" onclick="validateDialog('${uid(g.id)}')">Validate final</button>`:''}${v?.status==='disputed'&&canManage()?'<button class="secondary" onclick="go(\'office\')">Review dispute</button>':''}</div>`}
function validateDialog(id){const g=games().find(g=>g.id===id),v=h2hMeta.results?.find(x=>x.game_id===id);if(!g||!v||v.opponent_person!==myCoach()||v.status!=='pending')return;openSheet('Validate final',title('Entered by '+v.submitted_name,g.away+' at '+g.home)+card(g)+`<form id="validationForm"><label for="validationNote">If incorrect, describe the issue</label><textarea id="validationNote" name="note" maxlength="500"></textarea>${formStatus()}<button type="button" class="primary" onclick="validateFinal('${uid(id)}',true,this.form)">Confirm final</button><button type="button" class="secondary" onclick="validateFinal('${uid(id)}',false,this.form)">Flag incorrect score</button></form>`)}
async function validateFinal(id,confirm,form){const v=h2hMeta.results?.find(v=>v.game_id===id),note=form.elements.note.value.trim();if(!v||v.opponent_person!==myCoach()||v.submitted_by===myCoach())return;if(!confirm&&!note)return setFormMessage('Describe the incorrect score before flagging it.');await writeAction('validate_h2h_result',{p_game_id:id,p_version:v.version,p_home_score:v.home_score,p_away_score:v.away_score,p_confirm:confirm,p_note:note||null},form,async()=>{closeSheet();notice=confirm?'Final confirmed.':'Flagged for commissioner review.';await refreshCurrent('game',id)})}
async function openAddGame(){if(!actionsEnabled()||!ownProgram())return;const key=context();gameOptions=[];entryError='';go('addgame');try{const rows=await readRpc('get_schedule_team_options',{p_season_id:season.season_id});if(key!==context())return;gameOptions=Array.isArray(rows)?rows:[];if(route==='addgame'){const select=$('opponent');if(select){const selected=select.value;select.innerHTML=opponentOptions();select.value=selected}else render()}}catch(e){if(key===context()){entryError=e.message;if(route==='addgame')setFormMessage(entryError)}}}
function opponentOptions(){return `<option value="">Choose opponent</option><option value="bye">Bye week</option>${gameOptions.filter(t=>t.team_id!==myTeam()).map(t=>`<option value="${uid(t.team_id)}">${esc(t.team_name)}${t.claimed?' · '+esc(t.claimed_by||'Foundry coach'):''}</option>`).join('')}`}
function addGamePage(){if(!ownProgram()||!activeSeason())return empty('An active team assignment is required.');return title(ownProgram().team_name,'Add a matchup')+`<form class="compact-form" onsubmit="event.preventDefault();addGame(this)">${field('gameWeek','Week','number',`min="0" max="30" step="1" value="${week}" required`)}<label for="opponent">Opponent</label><select name="opponent" id="opponent" required>${opponentOptions()}</select><label for="side">Location</label><select name="side" id="side"><option value="home">Home</option><option value="away">Away</option></select><label for="gameType">Game type</label><select name="gameType" id="gameType"><option value="regular_season">Regular season</option><option value="bowl">Bowl</option><option value="conference_championship">Conference championship</option><option value="playoff">Playoff</option><option value="national_championship">National championship</option></select>${field('gameEvent','Event name (optional)','text','maxlength="150"')}${formStatus()}${entryError?`<p class="error-message">${esc(entryError)}</p>`:''}<button class="primary" type="submit">Add matchup</button></form>`}
async function addGame(form){if(!activeSeason()||!ownProgram())return;const w=Number(form.elements.gameWeek.value),opp=form.elements.opponent.value;if(form.elements.gameWeek.value.trim()===''||!Number.isInteger(w)||w<0||w>30||!opp)return setFormMessage('Choose a valid week and opponent.');const bye=opp==='bye',t=gameOptions.find(t=>t.team_id===opp);if(!bye&&!t)return setFormMessage('Choose an available opponent.');let type=form.elements.gameType.value;if(type==='regular_season'){const n=s=>String(s||'').toLowerCase().trim(),a=n(ownProgram().conference),b=n(t?.conference);if(a&&b)type=a===b?'conference':'non_conference'}const payload=bye?{p_season_id:season.season_id,p_week_number:w}:{p_season_id:season.season_id,p_week_number:w,p_opponent_team_id:opp,p_my_side:form.elements.side.value,p_game_type:type,p_event_name:form.elements.gameEvent.value.trim()||null,p_network:null,p_kickoff_time:null,p_my_rank:null,p_opponent_rank:null};await writeAction(bye?'create_my_schedule_bye':'create_my_schedule_game',payload,form,async()=>{notice=bye?'Bye week added.':'Matchup added.';await refreshCurrent('scores');week=w;render()})}
let officeData=null,officeLoadedFor='';
function officeCoaches(){return (model.coachStreams||[]).filter(c=>c.person_id&&String(c.current_season_id)===String(season?.season_id)&&c.current_team_id)}
function officePage(){
 if(!canManage())return empty('Commissioner tools require a commissioner role.');
 const coaches=officeCoaches(),streamList=(model.coachStreams||[]).filter(c=>c.person_id);
 const started=games().some(g=>g.final),slate=games().filter(g=>!g.is_bye);
 const disputed=(h2hMeta.results||[]).filter(v=>v.status==='disputed');
 let h=title(dynasty.name,'League office','Keep the season moving.')+`<div class="office-grid"><section>${section('Active week')}<form class="compact-form" onsubmit="event.preventDefault();saveWeek(this)">${field('activeWeek','Week number','number',`min="0" max="30" step="1" value="${week}" required`)}${formStatus()}<button class="primary" type="submit">Update active week</button></form></section><section>${section('Invite a coach')}<form class="compact-form" onsubmit="event.preventDefault();createInvite(this)">${field('inviteUses','Maximum uses','number','min="1" max="100" step="1" value="1" required')}<p class="muted">Invitations grant member access to this league.</p><p id="inviteMessage" role="status" class="muted"></p><button class="primary" type="submit">Create invitation</button></form></section></div>`;
 h+=`${section('Active invitations')}<div id="officeInvites"><p class="muted">Loading invitations…</p></div>`;
 if(!activeSeason()){h+=row('Open the active season','Select the current season to use the commissioner desk',`onclick="go('seasons')"`);setTimeout(()=>loadOfficeData(),0);return h}
 h+=`${section('Coach streams')}<form class="compact-form" onsubmit="event.preventDefault();saveStream(this)"><label for="streamCoach">Coach</label><select id="streamCoach" name="streamCoach" onchange="fillStreamForm(this)"><option value="">Select coach</option>${streamList.map(c=>`<option value="${uid(c.person_id)}">${esc(c.coach_name)}${c.current_team_name?' · '+esc(c.current_team_name):''}</option>`).join('')}</select><label for="streamPlatform">Platform</label><select id="streamPlatform" name="streamPlatform"><option>Twitch</option><option>YouTube</option><option>X</option><option>Other</option></select>${field('streamUrl','Stream URL','url','placeholder="https://…"')}${formStatus()}<button class="primary" type="submit">Save stream</button></form><div class="office-list">${streamList.map(c=>`<div class="office-list-row"><div><b>${esc(c.coach_name)}</b><div class="muted">${c.stream_url?esc(c.stream_platform||'Stream')+' · Configured':'No live stream configured'}</div></div></div>`).join('')||'<p class="muted">No coaches yet.</p>'}</div>`;
 h+=`${section('Correct a final')}<p class="muted">Enter or correct the final score for any game in this season, including disputed finals.</p>${disputed.length?`<div class="notice"><strong>Flagged for review</strong><p>${disputed.map(v=>{const g=games().find(x=>x.id===v.game_id);return g?esc(g.away)+' at '+esc(g.home):''}).filter(Boolean).join(' · ')}</p></div>`:''}<form class="compact-form" onsubmit="event.preventDefault();beginCorrection(this.elements.correctGame.value)"><label for="correctGame">Game</label><select id="correctGame" name="correctGame">${slate.map(g=>`<option value="${uid(g.id)}">Wk ${esc(g.week_number)} · ${esc(g.away)} at ${esc(g.home)}${g.final?' · Final '+esc(g.a)+'–'+esc(g.h):' · Not final'}</option>`).join('')}</select>${formStatus()}<button class="primary" type="submit">Open score editor</button></form>`;
 const weekGames=games().filter(g=>!g.is_bye&&Number(g.week_number)===Number(week));
 h+=`${section('Market Desk')}<form class="compact-form" onsubmit="event.preventDefault();generateVegasWeek(this)">${field('vegasWeek','Week number','number',`min="0" max="30" step="1" value="${week}" required`)}${formStatus()}<button class="primary" type="submit">Generate lines for week</button></form><form class="compact-form" onsubmit="event.preventDefault();generateVegasLine(this)"><label for="vegasGame">Game (active week)</label><select id="vegasGame" name="vegasGame">${weekGames.map(g=>`<option value="${uid(g.id)}">${esc(g.away)} at ${esc(g.home)}</option>`).join('')||'<option value="">No games this week</option>'}</select>${formStatus()}<button class="secondary" type="submit">Generate this line</button></form><p class="muted">Lines are generated by the dynasty model for every game on the slate.</p>`;
 const seasonOptions=model.seasons.slice().sort((a,b)=>Number(b.season_number)-Number(a.season_number));
 h+=`${section('National awards')}<form class="compact-form" onsubmit="event.preventDefault();addHeisman(this)"><label for="heismanSeason">Season</label><select id="heismanSeason" name="heismanSeason">${seasonOptions.map(s=>`<option value="${uid(s.season_id)}"${s.season_id===season.season_id?' selected':''}>Season ${esc(s.season_number)}${s.year?' · '+esc(s.year):''}${s.is_active?' · ACTIVE':''}</option>`).join('')}</select><label for="heismanCoach">Coach</label><select id="heismanCoach" name="heismanCoach"><option value="">Select coach</option>${streamList.map(c=>`<option value="${uid(c.person_id)}">${esc(c.coach_name)}</option>`).join('')}</select>${field('heismanPlayer','Player name','text','required maxlength="80"')}${field('heismanPosition','Position','text','maxlength="20" placeholder="QB"')}${field('heismanAward','Award name','text','value="Heisman Trophy" required maxlength="80"')}${formStatus()}<button class="primary" type="submit">Add award</button></form><div id="officeHeismans"><p class="muted">Loading awards…</p></div>`;
 h+=`<div id="officePrograms">${section('Change programs')}</div><form class="compact-form" onsubmit="event.preventDefault();changeProgram(this)"><label for="moveCoach">Coach</label><select id="moveCoach" name="moveCoach"><option value="">Select coach</option>${coaches.map(c=>`<option value="${uid(c.person_id)}">${esc(c.coach_name)} · ${esc(c.current_team_name||'')}</option>`).join('')}</select><label for="moveTeam">Destination program</label><select id="moveTeam" name="moveTeam"><option value="">Loading programs…</option></select><label for="moveReason">Reason (optional)</label><textarea id="moveReason" name="moveReason" maxlength="300" placeholder="Storyline reason — e.g. 'Accepted the challenge of rebuilding a former power.'"></textarea>${started?'<p class="muted">Coaching changes are locked once games begin. Start the next season before changing programs.</p>':''}${formStatus()}<button class="primary" type="submit" ${started?'disabled':''}>Change program</button></form><div id="officeMoves"><p class="muted">Loading coaching moves…</p></div>`;
 h+=`${section('Retire coach')}<p class="muted">Remove a coach from active participation while preserving the complete career ledger, completed games, trophies and historical records.</p><div class="office-list">${model.programs.filter(p=>p.person_id).map(p=>`<form class="office-list-row" onsubmit="event.preventDefault();retireCoach(this)"><input type="hidden" name="teamId" value="${uid(p.team_id)}"><div><b>${esc(p.coach_name||'Coach')}</b><div class="muted">${esc(p.team_name)}</div></div><button class="secondary" type="submit">Retire</button></form>`).join('')||'<p class="muted">No active coaches to retire.</p>'}</div>`;
 h+=`<div id="officeRollover">${section('Start next season')}</div><form class="compact-form" onsubmit="event.preventDefault();submitRollover(this)">${field('rolloverYear','Season year','number',`min="2020" max="2100" step="1" placeholder="${season.year?Number(season.year)+1:''}"`)}<div id="rolloverPanel"><p class="muted">Loading coach assignments…</p></div>${formStatus()}<button class="primary" type="submit">Review and start season</button></form>`;
 h+=`<p class="sport-note">Everything in the League Office runs natively — commissioner work no longer needs the legacy tools.</p>`;
 setTimeout(()=>loadOfficeData(),0);
 return h;
}
const formMsg=(form,t)=>{const m=form?.querySelector('[role="alert"]');if(m)m.textContent=t};
async function loadOfficeData(force=false){
 if(!canManage()||route!=='office')return;
 const key=context();
 if(!force&&officeLoadedFor===key){if(officeData)fillOfficeData();return}
 officeLoadedFor=key;const serial=loadSerial;
 try{
  const [invites,heismans,moves,teamRows]=await Promise.all([readRpc('list_dynasty_invites',{p_dynasty_id:dynasty.dynasty_id}),readRpc('list_heisman_awards',{p_dynasty_id:dynasty.dynasty_id}),readRpc('get_coach_program_moves',{p_dynasty_id:dynasty.dynasty_id}),readRpc('get_team_selection',{p_season_id:season.season_id})]);
  if(serial!==loadSerial||key!==context()||route!=='office')return;
  officeData={invites:Array.isArray(invites)?invites:[],heismans:Array.isArray(heismans)?heismans:[],moves:Array.isArray(moves)?moves:[],teamRows:[...new Map((Array.isArray(teamRows)?teamRows:[]).map(t=>[String(t.team_id),t])).values()].filter(t=>t.team_id)};
  fillOfficeData();
 }catch(e){officeLoadedFor='';const el=$('officeInvites');if(el)el.innerHTML='<p class="muted">Could not load the commissioner lists. Reopen the League Office to retry.</p>'}
}
function fillOfficeData(){
 const d=officeData;if(!d)return;
 const inv=$('officeInvites');
 if(inv)inv.innerHTML=d.invites.filter(x=>x.active).map(x=>{const used=Number(x.use_count||0),max=Number(x.max_uses||0),role=String(x.role||'member')==='co_commissioner'?'Co-Commissioner':'Member',created=x.created_at?new Date(x.created_at).toLocaleDateString():'—';return `<form class="office-list-row" onsubmit="event.preventDefault();revokeInvite(this)"><input type="hidden" name="inviteId" value="${uid(x.invite_id||x.id)}"><div><b>${role} · ${Math.max(0,max-used)}/${max} uses remaining</b><div class="muted">Created ${esc(created)} · ${used} used</div></div><button class="secondary" type="submit">Revoke</button></form>`}).join('')||'<p class="muted">No active invitations.</p>';
 const hei=$('officeHeismans');
 if(hei)hei.innerHTML=d.heismans.map(a=>`<form class="office-list-row" onsubmit="event.preventDefault();deleteHeisman(this)"><input type="hidden" name="awardId" value="${uid(a.award_id||a.id)}"><div><b>${esc(a.award_name||'Heisman Trophy')} · Season ${esc(a.season_number??'')}</b><div class="muted">${esc(a.player_name||'')}${a.position?' · '+esc(a.position):''}${a.coach_name?' · '+esc(a.coach_name):''}${a.team_name?' · '+esc(a.team_name):''}</div></div><button class="secondary" type="submit">Remove</button></form>`).join('')||'<p class="muted">No awards recorded yet.</p>';
 const mv=$('officeMoves');
 if(mv){const rows=d.moves.slice(0,6).map(m=>`<div class="office-list-row"><div><b>${esc(m.coach_name)} · ${esc(m.from_team_name||'Unassigned')} → ${esc(m.to_team_name||'')}</b><div class="muted">Season ${esc(m.season_number??'')}${m.reason?' · '+esc(m.reason):''}</div></div></div>`).join('');mv.innerHTML=rows?`<div class="office-list">${rows}</div>`:'<p class="muted">No coaching changes recorded yet.</p>'}
 const mt=$('moveTeam');
 if(mt){const cur=mt.value;mt.innerHTML='<option value="">Select destination</option>'+d.teamRows.filter(t=>!t.claimed).map(t=>`<option value="${uid(t.team_id)}">${esc(t.team_name)}${t.conference?' · '+esc(t.conference):''}</option>`).join('');if(cur)mt.value=cur}
 const rp=$('rolloverPanel');
 if(rp){const coaches=officeCoaches();rp.innerHTML=coaches.map(c=>`<label for="roll_${uid(c.person_id)}">${esc(c.coach_name)} — current: ${esc(c.current_team_name||'Unassigned')}</label><select id="roll_${uid(c.person_id)}" name="roll_${uid(c.person_id)}" data-rollover-coach="${uid(c.person_id)}" required><option value="">Select Stay or Change…</option>${d.teamRows.map(t=>{const same=String(t.team_id)===String(c.current_team_id);return `<option value="${uid(t.team_id)}">${same?'Stay · ':'Change · '}${esc(t.team_name)}${t.claimed&&!same?' · currently '+esc(t.claimed_by||'claimed'):''}</option>`}).join('')}</select>`).join('')||'<p class="muted">No active coaches were found in this season.</p>'}
}
async function revokeInvite(form){if(!confirm('Revoke this invitation? It will no longer work for joining the league.'))return;await writeAction('revoke_dynasty_invite',{p_invite_id:form.elements.inviteId.value},form,async()=>{notice='Invitation revoked.';await refreshCurrent('office')})}
function fillStreamForm(sel){const c=(model.coachStreams||[]).find(x=>String(x.person_id)===String(sel.value)),f=sel.form;if(!f)return;if(c){f.elements.streamPlatform.value=c.stream_platform||'Other';f.elements.streamUrl.value=c.stream_url||''}else f.elements.streamUrl.value=''}
async function saveStream(form){const personId=form.elements.streamCoach.value;if(!personId)return formMsg(form,'Select a coach first.');await writeAction('set_coach_stream',{p_dynasty_id:dynasty.dynasty_id,p_person_id:personId,p_platform:form.elements.streamPlatform.value||null,p_url:form.elements.streamUrl.value.trim()||null},form,async()=>{notice='Stream saved.';await refreshCurrent('office')})}
function beginCorrection(id){if(!canManage())return;const g=games().find(g=>g.id===id);if(!g||g.is_bye)return;resultDraft={gameId:id,context:context(),seasonId:season.season_id,myTeamId:g.team_id,correction:true,away:g.final?g.a:'',home:g.final?g.h:'',overtime:!!g.overtime};selectedGame=id;go('result')}
async function generateVegasWeek(form){const w=Number(form.elements.vegasWeek.value);if(form.elements.vegasWeek.value.trim()===''||!Number.isInteger(w)||w<0||w>30)return formMsg(form,'Enter a valid week.');await writeAction('generate_dynasty_vegas_week',{p_dynasty_id:dynasty.dynasty_id,p_season_id:season.season_id,p_week_number:w},form,async()=>{notice='Dynasty lines generated for week '+w+'.';await refreshCurrent('office')})}
async function generateVegasLine(form){const id=form.elements.vegasGame.value;if(!id)return formMsg(form,'No game selected.');await writeAction('generate_dynasty_vegas_line',{p_game_id:id},form,async()=>{notice='Dynasty line generated.';await refreshCurrent('office')})}
async function addHeisman(form){const personId=form.elements.heismanCoach.value;if(!personId)return formMsg(form,'Select the winning coach.');await writeAction('create_heisman_award',{p_dynasty_id:dynasty.dynasty_id,p_season_id:form.elements.heismanSeason.value,p_person_id:personId,p_player_name:form.elements.heismanPlayer.value.trim()||null,p_position:form.elements.heismanPosition.value.trim()||null,p_award_name:form.elements.heismanAward.value.trim()||'Heisman Trophy'},form,async()=>{notice='Award added. Trophy Room updated.';await refreshCurrent('office')})}
async function deleteHeisman(form){if(!confirm('Remove this award record?'))return;await writeAction('delete_heisman_award',{p_award_id:form.elements.awardId.value},form,async()=>{notice='Award removed.';await refreshCurrent('office')})}
async function changeProgram(form){const personId=form.elements.moveCoach.value,teamId=form.elements.moveTeam.value;if(!personId||!teamId)return formMsg(form,'Select a coach and a destination program.');if(games().some(g=>g.final))return formMsg(form,'Coaching changes are locked once games begin.');const coach=officeCoaches().find(c=>String(c.person_id)===String(personId)),team=(officeData?.teamRows||[]).find(t=>String(t.team_id)===String(teamId));if(!confirm(`Move ${coach?.coach_name||'this coach'} to ${team?.team_name||'the new program'}? Career history is preserved.`))return;await writeAction('commissioner_change_coach_program',{p_season_id:season.season_id,p_person_id:personId,p_new_team_id:teamId,p_reason:form.elements.moveReason.value.trim()||null},form,async()=>{notice='Program changed. Career history preserved.';await refreshCurrent('office')})}
async function retireCoach(form){const teamId=form.elements.teamId.value,p=model.programs.find(x=>String(x.team_id)===String(teamId)),coach=p?.coach_name||'This coach',team=p?.team_name||'the program';if(!confirm(`Retire ${coach} from ${team}? The complete career ledger, completed games, trophies and historical records are preserved. ${team} will become available for another coach.`))return;await writeAction('release_team',{p_season_id:season.season_id,p_team_id:teamId},form,async()=>{notice=coach+' retired. Career history preserved.';await refreshCurrent('office')})}
async function submitRollover(form){
 const yearRaw=form.elements.rolloverYear.value.trim(),year=yearRaw?Number(yearRaw):null;
 if(year!==null&&(!Number.isInteger(year)||year<2020||year>2100))return formMsg(form,'Enter a valid four-digit season year.');
 const selects=[...form.querySelectorAll('select[data-rollover-coach]')];
 if(!selects.length)return formMsg(form,'No active coaches were found in this season. Nothing was changed.');
 const assignments=selects.map(s=>({person_id:s.dataset.rolloverCoach,team_id:s.value,confirmed:true}));
 if(assignments.some(a=>!a.team_id))return formMsg(form,'Select Stay or Change for every active coach.');
 if(new Set(assignments.map(a=>a.team_id)).size!==assignments.length)return formMsg(form,'A school can only be assigned to one coach. Resolve the duplicate first.');
 const summary=selects.map(s=>{const c=officeCoaches().find(x=>String(x.person_id)===s.dataset.rolloverCoach);return (c?.coach_name||'Coach')+' → '+s.selectedOptions[0].text}).join('\n');
 if(!confirm('Review Season '+(Number(season.season_number)+1)+' assignments:\n\n'+summary+'\n\nCreate this season and archive the current one?'))return;
 await writeAction('create_next_season_with_programs',{p_dynasty_id:dynasty.dynasty_id,p_expected_season_id:season.season_id,p_year:year,p_assignments:assignments},form,async()=>{notice='Season '+(Number(season.season_number)+1)+' created with coach assignments saved.';await refreshCurrent('seasons')});
}
async function saveWeek(form){if(!canManage()||!activeSeason())return setFormMessage('Select the active season first.');const w=Number(form.elements.activeWeek.value);if(form.elements.activeWeek.value.trim()===''||!Number.isInteger(w)||w<0||w>30)return setFormMessage('Enter a valid week.');await writeAction('set_dynasty_active_week',{p_dynasty_id:dynasty.dynasty_id,p_week:w},form,async()=>{notice='Active week updated.';await refreshCurrent('office')})}
async function createInvite(form){if(!canManage())return;const n=Number(form.elements.inviteUses.value);if(!Number.isInteger(n)||n<1||n>100)return;await writeAction('create_dynasty_invite',{p_dynasty_id:dynasty.dynasty_id,p_max_uses:n,p_role:'member'},form,async result=>{const r=Array.isArray(result)?result[0]:result,code=r?.code||r?.invite_code||r;const el=$('inviteMessage');el.textContent=typeof code==='string'?code:'Invitation created — see Active invitations below.';el.classList.add('invite-code');setFormMessage('');officeLoadedFor='';loadOfficeData(true)})}
function marketLineFor(g){return marketContext===context()?marketRows.find(v=>String(v.game_id||v.id)===String(g.id)):null}
function lineNumber(value){return value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))?Number(value):null}
function dynastyLineBody(g){
 const v=marketLineFor(g),spread=lineNumber(v?.spread_home),total=lineNumber(v?.total_line);
 if(!v||spread===null&&total===null){const message=marketStatus==='loading'||marketStatus==='idle'?'Loading dynasty line…':marketStatus==='error'?'Dynasty line unavailable':'Dynasty line not posted';return `<span class="line-empty">${message}</span>${marketStatus==='error'?'<button class="textlink" onclick="loadMarketLines()">Retry</button>':''}`}
 const favorite=spread===null?'Spread —':spread===0?'Pick’em':(spread<0?g.home:g.away)+' −'+Math.abs(spread);
 const away=lineNumber(v.projected_away_score),home=lineNumber(v.projected_home_score),prob=lineNumber(v.home_win_probability);
 return `<div class="dynasty-line-head"><span>DYNASTY LINE</span>${v.locked_at?'<span>LOCKED</span>':''}</div><div class="dynasty-line-values"><strong>${esc(favorite)}</strong><span>O/U <b>${total===null?'—':esc(total)}</b></span></div>${away!==null&&home!==null||prob!==null?`<div class="dynasty-line-detail">${away!==null&&home!==null?`<span>Projected ${esc(g.away)} ${esc(away)} · ${esc(g.home)} ${esc(home)}</span>`:''}${prob!==null?`<span>${esc(g.home)} win ${Math.round(prob*100)}%</span>`:''}</div>`:''}`;
}
function winProbMeter(g){
 const v=marketLineFor(g),prob=lineNumber(v?.home_win_probability);
 if(prob===null)return '';
 const homePct=Math.round(prob*100),awayPct=100-homePct;
 return `<div class="winprob" role="img" aria-label="Win probability: ${esc(g.away)} ${awayPct} percent, ${esc(g.home)} ${homePct} percent"><div class="winprob-head"><span>WIN PROBABILITY</span><span>${esc(g.away)} ${awayPct}% · ${esc(g.home)} ${homePct}%</span></div><div class="winprob-bar"><span class="winprob-away" style="width:${awayPct}%"></span><span class="winprob-home" style="width:${homePct}%"></span></div></div>`;
}
function dynastyLine(g){return `<div class="dynasty-line" data-dynasty-line="${uid(g.id)}">${dynastyLineBody(g)}</div>`}
function refreshLineCards(){document.querySelectorAll('[data-dynasty-line]').forEach(el=>{const g=games().find(g=>g.id===el.dataset.dynastyLine);if(g)el.innerHTML=dynastyLineBody(g)})}
async function loadMarketLines(){
 if(!dynasty||!season)return;
 const key=context(),serial=loadSerial;
 if(marketRequest?.key===key&&marketRequest.serial===serial)return marketRequest.promise;
 if(marketContext===key&&marketStatus==='loaded')return;
 marketStatus='loading';refreshLineCards();
 const request={key,serial,promise:null};marketRequest=request;
 request.promise=(async()=>{try{
  const rows=[];
  for(let offset=0;;offset+=500){const page=await req(`/rest/v1/rpc/get_dynasty_vegas?limit=500&offset=${offset}&order=id.asc,team_id.asc`,{method:'POST',body:{p_dynasty_id:dynasty.dynasty_id,p_season_id:season.season_id},token:session()?.access_token});if(!Array.isArray(page))throw Error('Market unavailable.');rows.push(...page);if(page.length<500)break;if(key!==context()||serial!==loadSerial)return}
  if(key!==context()||serial!==loadSerial)return;
  marketRows=rows;marketStatus='loaded';marketContext=key;
 }catch(e){if(key!==context()||serial!==loadSerial)return;marketStatus='error';entryError=e.message}
 finally{if(marketRequest===request)marketRequest=null}
 if(key===context()&&serial===loadSerial){refreshLineCards();if(route==='market')render()}
 })();return request.promise;
}
async function maybeAutoGenerateLines(){
 if(!canManage()||!season?.is_active||mutationPending||marketStatus!=='loaded')return;
 const key=context()+':w'+week;
 if(marketAutoGenFor===key)return;marketAutoGenFor=key;
 const missing=games().filter(g=>{if(g.is_bye||Number(g.week_number)!==Number(week))return false;const v=marketLineFor(g);return !v||(lineNumber(v.spread_home)===null&&lineNumber(v.total_line)===null)});
 if(!missing.length)return;
 try{
  await req('/rest/v1/rpc/generate_dynasty_vegas_week',{method:'POST',token:session()?.access_token,body:{p_dynasty_id:dynasty.dynasty_id,p_season_id:season.season_id,p_week_number:Number(week)},retry:0});
  if(key!==context()+':w'+week)return;
  marketStatus='idle';marketContext='';marketRequest=null;
  await loadMarketLines();
 }catch{/* Lines can still be generated manually from the Market Desk. */}
}
function weekProgress(w){
 const human=new Set(model.programs.filter(p=>p.person_id).map(p=>String(p.team_id)));
 const slate=games().filter(g=>Number(g.week_number)===Number(w)&&!g.is_bye&&g.status!=='cancelled'&&(human.has(String(g.team_id))||human.has(String(g.opponent_team_id))||g.person_id||g.opponent_person_id));
 const pending=slate.filter(g=>!g.final);
 const waiting=[...new Set(pending.flatMap(g=>[g.team_id,g.opponent_team_id]).filter(id=>human.has(String(id))).map(id=>model.programs.find(p=>String(p.team_id)===String(id))?.coach_name).filter(Boolean))];
 return {total:slate.length,done:slate.length-pending.length,pending,waiting};
}
function weekProgressStrip(){
 if(!season?.is_active)return '';
 const p=weekProgress(week);if(!p.total)return '';
 const maxWeek=Math.max(0,...games().map(g=>Number(g.week_number)||0));
 const sub=p.pending.length?('Waiting on '+p.waiting.join(', ')):(Number(week)>=maxWeek?'All in — the season is complete':'All in — the week advances automatically');
 return `<div class="week-progress"><strong>Week ${esc(week)} · ${p.done} of ${p.total} coach games in</strong><span>${esc(sub)}</span></div>`;
}
async function maybeAutoAdvanceWeek(){
 if(!canManage()||!season?.is_active||mutationPending)return;
 const key=context()+':w'+week;
 if(autoAdvanceFor===key)return;autoAdvanceFor=key;
 const p=weekProgress(week);
 if(!p.total||p.pending.length)return;
 const maxWeek=Math.max(0,...games().map(g=>Number(g.week_number)||0));
 if(Number(week)>=maxWeek)return;
 try{
  const stored=await readRpc('get_dynasty_active_week',{p_dynasty_id:dynasty.dynasty_id});
  if(stored!=null&&Number(stored)!==Number(week))return;
  await req('/rest/v1/rpc/set_dynasty_active_week',{method:'POST',token:session()?.access_token,body:{p_dynasty_id:dynasty.dynasty_id,p_week:Number(week)+1},retry:0});
  if(context()+':w'+week!==key)return;
  week=Number(week)+1;
  notice='All coach games were in — advanced to Week '+week+'.';
  if(!document.querySelector('#mainContent form')&&!$('detailSheet')?.open)render();
 }catch{/* The week can still be advanced manually in the League Office. */}
}
let bracketRound=null;
function bracketData(){
 const isCfp=g=>{const t=String(g.game_type||'').toLowerCase();return t==='playoff'||t==='cfp'};
 const post=games().filter(g=>!g.is_bye&&(isCfp(g)||String(g.game_type||'').toLowerCase()==='national_championship'));
 const byeTeams=model.scheduleGames.filter(g=>{if(!g?.is_bye)return false;const en=String(g?.event_name||''),gt=String(g?.game_type||'').toLowerCase(),wk=Number(g?.week_number||0);return /CFP|playoff|first round bye/i.test(en)||/cfp|playoff/.test(gt)||wk>=16});
 if(!post.length&&!byeTeams.length)return null;
 const natty=post.filter(g=>String(g.game_type||'').toLowerCase()==='national_championship');
 const cfpGames=post.filter(isCfp);
 const weeks=[...new Set(cfpGames.map(g=>Number(g.week_number||0)).filter(w=>w>0&&w<900))].sort((a,b)=>a-b);
 const sizes=[4,4,2,1];
 const tbd=(r,i)=>({id:`cfp-tbd-r${r}-${i}`,synthetic:true,away:'TBD',home:'TBD',awayId:null,homeId:null,final:false});
 const shortName=n=>{n=String(n||'').trim();return n&&n.toUpperCase()!=='TBD'?n:''};
 const winnerOf=(g1,g2)=>{const m1=[shortName(g1?.away),shortName(g1?.home)].filter(Boolean).join('/'),m2=[shortName(g2?.away),shortName(g2?.home)].filter(Boolean).join('/');if(m1&&m2)return[`Winner of ${m1}`,`Winner of ${m2}`];if(m1)return[`Winner of ${m1}`,'TBD'];if(m2)return['TBD',`Winner of ${m2}`];return['TBD','TBD']};
 const rounds=[];
 for(let r=0;r<4;r++){
  let roundGames=[];
  if(r===3&&natty.length)roundGames=natty.slice(0,1);
  else if(r<weeks.length)roundGames=cfpGames.filter(g=>Number(g.week_number||0)===weeks[r]);
  if(r===1&&byeTeams.length){
   const slots=sizes[r]-roundGames.length,r1=rounds[0]||[];
   for(let i=0;i<Math.min(byeTeams.length,slots);i++){
    const bt=byeTeams[i];let opp='TBD';const r1g=r1[i];
    if(r1g){const m=[shortName(r1g.away),shortName(r1g.home)].filter(Boolean).join('/');if(m)opp='Winner of '+m}
    roundGames.push({id:'cfp-bye-'+(bt.id||i),synthetic:true,away:opp,home:bt.team_name||'TBD',awayId:null,homeId:bt.team_id||null,final:false,event_name:'CFP Quarterfinal — First Round Bye'});
   }
  }
  if(r===1&&rounds.length){
   const prev=rounds[0]||[];
   for(let i=roundGames.length;i<sizes[r];i++){
    const[w1,w2]=winnerOf(prev[(i*2)%prev.length],prev[(i*2+1)%prev.length]);
    roundGames.push({id:`cfp-tbd-r${r}-${i}`,synthetic:true,away:w2,home:w1,awayId:null,homeId:null,final:false});
   }
  }else{
   while(roundGames.length<sizes[r])roundGames.push(tbd(r,roundGames.length));
  }
  rounds.push(roundGames.slice(0,sizes[r]));
 }
 return {rounds,weeks,natty};
}
function bracketActiveRound(data){
 if(bracketRound!=null)return Math.max(0,Math.min(3,bracketRound));
 const roundWeeks=data.rounds.map((_,r)=>r===3&&data.natty.length?Number(data.natty[0].week_number||0):(r<data.weeks.length?data.weeks[r]:0));
 let best=0;for(let i=0;i<roundWeeks.length;i++)if(roundWeeks[i]&&Number(week)>=roundWeeks[i])best=i;
 const hasContent=rs=>rs.some(g=>{const a=String(g.away||'').toUpperCase(),h=String(g.home||'').toUpperCase();return (a&&a!=='TBD'&&!a.startsWith('WINNER OF'))||(h&&h!=='TBD'&&!h.startsWith('WINNER OF'))});
 if(!hasContent(data.rounds[best]))for(let i=data.rounds.length-1;i>best;i--)if(hasContent(data.rounds[i])){best=i;break}
 return best;
}
function setBracketRound(i){bracketRound=i;render()}
function bracketGameHTML(g,isChamp){
 const decided=g.final&&g.a!=null&&g.h!=null&&g.a!==g.h;
 const homeEntry=String(g.team_id)===String(g.homeId),homeRank=homeEntry?g.team_rank:g.opponent_rank,awayRank=homeEntry?g.opponent_rank:g.team_rank;
 const row=(name,id,score,rank,winner)=>`<div class="bracket-team${winner?' winner':''}">${logo(id,name)}<span>${rank?`<b class="bracket-rank">#${esc(rank)}</b>`:''}${esc(name||'TBD')}</span><b>${score??''}</b></div>`;
 const label=g.event_name||(isChamp?'National Championship':'College Football Playoff');
 const inner=`<div class="bracket-game-head"><span>${esc(label)}</span><strong>${g.final?'FINAL':'UPCOMING'}</strong></div>${row(g.away,g.awayId,g.final?g.a:'',awayRank,decided&&g.a>g.h)}${row(g.home,g.homeId,g.final?g.h:'',homeRank,decided&&g.h>g.a)}`;
 return g.synthetic?`<article class="bracket-game${isChamp?' champ':''}">${inner}</article>`:`<article class="bracket-game${isChamp?' champ':''}"><button class="bracket-open" onclick="openGame('${uid(g.id)}')">${inner}</button></article>`;
}
function bracketSection(){
 if(scope!=='all')return '';
 const data=bracketData();if(!data)return '';
 const labels=['Round 1','Round 2','Semifinals','Championship'];
 const active=bracketActiveRound(data);
 return `<section class="bracket">${section('College Football Playoff')}<div class="filterbar bracket-pills">${labels.map((l,i)=>`<button class="${i===active?'sel':''}" aria-pressed="${i===active}" onclick="setBracketRound(${i})">${l}</button>`).join('')}</div>${data.rounds[active].map(g=>bracketGameHTML(g,active===3)).join('')}</section>`;
}
